  "Previous move": { es: "Jugada anterior", ar: "الحركة السابقة", zh: "上一手", sw: "Hatua iliyopita", sv: "Föregående drag", de: "Vorheriger Zug", pt: "Jogada anterior", fr: "Coup précédent" },
