  "🔍 Feedback on my last move": { es: "🔍 Comentario de mi última jugada", ar: "🔍 تعليق على حركتي الأخيرة", zh: "🔍 点评我的上一步", sw: "🔍 Maoni kuhusu hatua yangu ya mwisho", sv: "🔍 Återkoppling på mitt senaste drag", de: "🔍 Rückmeldung zu meinem letzten Zug", pt: "🔍 Comentário sobre minha última jogada", fr: "🔍 Avis sur mon dernier coup" },
  "Your coach": { es: "Tu entrenador", ar: "مدرّبك", zh: "你的教练", sw: "Kocha wako", sv: "Din tränare", de: "Dein Trainer", pt: "Seu treinador", fr: "Votre coach" },
  "Choose a board and a level and press": { es: "Elige un tablero y un nivel y pulsa", ar: "اختر لوحة ومستوى واضغط", zh: "选好棋盘和级别，然后按", sw: "Chagua ubao na kiwango kisha bonyeza", sv: "Välj bräde och nivå och tryck på", de: "Wähle Brett und Stufe und drücke", pt: "Escolha um tabuleiro e um nível e toque em", fr: "Choisissez un plateau et un niveau, puis appuyez sur" },
  "New game": { es: "Partida nueva", ar: "مباراة جديدة", zh: "新对局", sw: "Mchezo mpya", sv: "Nytt parti", de: "Neue Partie", pt: "Nova partida", fr: "Nouvelle partie" },
  ". While you play, press": { es: ". Mientras juegas, pulsa", ar: ". أثناء اللعب، اضغط", zh: "。下棋时，在落子前按", sw: ". Unapocheza, bonyeza", sv: ". Medan du spelar trycker du på", de: ". Während du spielst, drücke", pt: ". Enquanto joga, toque em", fr: ". Pendant la partie, appuyez sur" },
  "Advice": { es: "Consejo", ar: "نصيحة", zh: "建议", sw: "Ushauri", sv: "Råd", de: "Tipp", pt: "Conselho", fr: "Conseil" },
  "before a move or": { es: "antes de una jugada o", ar: "قبل الحركة أو", zh: "，或在落子后按", sw: "kabla ya hatua au", sv: "före ett drag eller", de: "vor einem Zug oder", pt: "antes de uma jogada ou", fr: "avant un coup ou" },
  "Feedback": { es: "Comentario", ar: "تعليق", zh: "点评", sw: "Maoni", sv: "Återkoppling", de: "Rückmeldung", pt: "Comentário", fr: "Avis" },
  "after one.": { es: "después.", ar: "بعدها.", zh: "。", sw: "baada yake.", sv: "efteråt.", de: "danach.", pt: "depois.", fr: "après." },
